'use strict';
const CONTACT_EMAIL='minjjjhhh@gmail.com';
const main=document.querySelector('main');
const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const finePointer=window.matchMedia('(hover:hover) and (pointer:fine)');
const services=[['Branding & Visual Identity',['브랜딩','브랜드 전략','키비주얼','브랜드 로고','타이포그래피'],'브랜드의 방향성을 설정하고 시각적 정체성을 만드는 분야'],['UI/UX Design',['사용자 리서치','정보 구조(IA)','UI 디자인','와이어프레임','프로토타입'],'사용자의 요구와 서비스 목적을 고려해 디지털 인터페이스를 설계하는 분야'],['Website Design',['웹 레이아웃','랜딩페이지','웹 UI','반응형 디자인'],'웹사이트의 정보와 시각 요소를 목적에 맞게 구성하는 분야'],['Visual & AI Design',['그래픽 디자인','아트 디렉션','무드보드','AI 이미지 제작'],'콘셉트를 이미지와 그래픽으로 구체화하는 분야']];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const graphemes=s=>typeof Intl.Segmenter==='function'?[...new Intl.Segmenter('ko',{granularity:'grapheme'}).segment(s)].map(s=>s.segment):Array.from(s);
const projects = [
  {slug:'mova',name:'MOVA',year:'2026',field:'브랜드 디자인 · 웹 디자인',description:'패션 브랜드 아이덴티티 및 웹·모바일 디자인',workDescription:'브래드기획 ∙ UI/UX디자인',tools:'Figma · AI 이미지 생성 도구',landingImage:'mova-landing.png',workImage:'mova-work.png',categories:['Branding','UI/UX Design','Website Design']},
  {slug:'movera',name:'MOVERA',year:'2026',field:'BX 디자인 · UX 리서치',description:'SPA 패션 브랜드 기획 및 랜딩페이지 콘셉트',workDescription:'브랜드 기획',tools:'Figma · AI',landingImage:'movera-landing.png',workImage:'movera-work.png',categories:['Branding','Strategy & Research']},
  {slug:'project-3',name:'프로젝트3',year:'2026',field:'디자인분야',description:'프로젝트 유형',tools:'사용툴',categories:[],pending:true},
  {slug:'project-4',name:'프로젝트4',year:'2026',field:'디자인분야',description:'프로젝트 유형',tools:'사용툴',categories:[],pending:true}
];

function media(label, extra='') {
  return `<div class="project-visual ${extra}"><span class="placeholder-label">${escapeHTML(label)}</span></div>`;
}

function projectCard(p, i, work=false) {
  const name=work?p.name:(p.landingName||p.name);
  const href=work?`#/work/${p.slug}`:'#/work';
  const image=work?p.workImage:p.landingImage;
  const pendingDetails=work&&p.pending;
  const body=`<div class="project-visual${image?' has-image':''}${p.slug==='mova'?' mova-visual':''}" ${pendingDetails?'':`data-cursor="${work?'View Project ↗':'View Work ↗'}"`}>${image?`<img class="project-image" src="assets/${image}" loading="lazy" alt="${name} ${work?'프로젝트 목업':'브랜드 비주얼'}">${p.slug==='mova'?'<div class="project-image-shade" aria-hidden="true"></div>':''}`:work?'<span class="placeholder-label">PROJECT VISUAL</span>':''}${p.pending?'':`<div class="marquee" aria-hidden="true"><div class="marquee-track">${Array.from({length:8},()=>`<span>${name} · ${p.year} ·</span>`).join('')}</div></div>`}</div>
    <div class="project-info"><h3>${name}</h3><div class="project-meta"><span>${p.field}</span><span>${work?(p.workDescription||p.description):p.description}</span>${work?'</div><div class="project-meta">':''}<span>${!work&&p.pending?'디자인툴':p.tools}</span><span>${p.year}</span><span class="project-link">${pendingDetails?'상세 준비 중':work?'상세 보기 ↗':'프로젝트 상세 보기 ↗'}</span></div></div>`;
  const attrs=`class="project-card reveal${pendingDetails?' is-pending':''}${!work&&p.pending?' landing-placeholder':''}" data-project="${p.slug}" style="--delay:${i%2*.1}s"`;
  return pendingDetails?`<article ${attrs} aria-label="${name} 준비 중">${body}</article>`:`<a ${attrs} href="${href}" aria-label="${name} ${work?'프로젝트 상세 보기':'Work 페이지 보기'}">${body}</a>`;
}

function contact() {
  return `<section class="section contact-section" id="contact" aria-labelledby="contact-title">
    <div class="section-heading reveal"><h2 id="contact-title">CONTACT</h2><p>채용 관련 연락은 아래 양식으로 남겨주세요.</p></div>
    <div class="contact-split"><div class="contact-profile reveal"><div class="contact-portrait"><img src="assets/contact.png" width="1254" height="1254" loading="lazy" alt="노트북 앞에서 디자인을 고민하는 지혜의 일러스트"><div class="socials"><button type="button" data-info="instagram" aria-label="Instagram 안내"><img src="assets/instagram.svg" width="22.5184" height="22.5184" alt=""></button><button type="button" data-info="profile" aria-label="프로필 안내"><img src="assets/user.svg" width="27.0221" height="27.0221" alt=""></button><button type="button" data-info="youtube" aria-label="YouTube 안내"><img src="assets/youtube.svg" width="27.0221" height="27.0221" alt=""></button></div></div><div class="contact-details"><a class="roll" href="mailto:${CONTACT_EMAIL}">${CONTACT_EMAIL}</a></div></div>
    <form class="contact-form reveal" novalidate>
      <div class="field"><label for="name">Name</label><input id="name" name="name" placeholder="이름을 입력해 주세요" autocomplete="name" required maxlength="100" aria-describedby="name-error"><p class="field-error" id="name-error"></p></div>
      <div class="field"><label for="email">Email</label><input id="email" name="email" type="email" placeholder="이메일을 입력해 주세요" autocomplete="email" required maxlength="254" aria-describedby="email-error"><p class="field-error" id="email-error"></p></div>
      <div class="field"><label for="service">Service · 서비스 선택</label><select id="service" name="service" required aria-describedby="service-error"><option value="">서비스 선택</option>${services.map(s=>`<option>${escapeHTML(s[0])}</option>`).join('')}<option>채용 문의</option><option>Other</option></select><p class="field-error" id="service-error"></p></div>
      <div class="field"><label for="message">Message</label><textarea id="message" name="message" placeholder="함께 나누고 싶은 이야기를 남겨주세요" required maxlength="4000" aria-describedby="message-error"></textarea><p class="field-error" id="message-error"></p></div>
      <button class="cta roll" type="submit">Send Message ↗</button><p class="form-note">메일 앱에서 작성한 내용을 확인하고 전송해 주세요.</p><p class="form-status" role="status" aria-live="polite"></p>
    </form></div></section>`;
}

function footer() {
  return `<footer class="footer"><div class="footer-name reveal" aria-label="Jihye Minⓜ"><span class="footer-letters" aria-hidden="true">${graphemes('Jihye Minⓜ').map(c=>`<span class="footer-letter${c==='ⓜ'?' footer-mark':''}">${c===' '?'&nbsp;':escapeHTML(c)}</span>`).join('')}</span></div><div class="footer-bottom"><p>Designed by <strong>MinJihye</strong></p><p><button type="button" class="roll" data-info="privacy">Privacy Policy</button> · <button type="button" class="roll" data-info="terms">Terms & Conditions</button></p><p><strong>© 2026</strong> All rights reserved</p></div></footer>`;
}

function landing() {
  const images=['branding','uiux','website','visual-ai'];
  return `<section class="hero" id="home" aria-label="디자이너 소개"><img class="hero-background" src="assets/hero-v2.png" width="1672" height="941" fetchpriority="high" alt=""><div class="hero-shade"></div><div class="hero-inner"><h1 class="hero-name" aria-label="Jihye Minⓜ">${graphemes('Jihye Minⓜ').map((c,i)=>`<span class="char-wrap" aria-hidden="true"><span class="hero-char" style="--i:${i}">${c===' '?'&nbsp;':escapeHTML(c)}</span></span>`).join('')}</h1><p class="hero-description">브랜드와 사람을 이해하고, 경험을 디자인합니다.</p></div><p class="hero-role">BX & Brand Design · UI/UX Design · Web Design</p></section>
    <section class="section featured" id="work" aria-labelledby="work-title"><a class="section-heading reveal" href="#/work"><h2 id="work-title" class="roll">FEATURED PROJECTS</h2><p>브랜드 기획부터 디지털 디자인까지, 다양한 프로젝트를 소개합니다.</p></a><div class="project-grid">${projects.slice(0,2).map((p,i)=>projectCard(p,i)).join('')}</div></section>
    <section class="section" id="services" aria-labelledby="services-title"><div class="section-heading reveal"><h2 id="services-title">What I Do</h2><p>UI·브랜딩부터 웹·모바일 제품의 전체 디자인까지</p></div><div class="service-grid">${services.map(([title,tags,desc],i)=>`<article class="service-card reveal" style="--delay:${i%2*.1}s"><div class="service-visual"><img src="assets/${images[i]}.png" width="${i===1?1672:1536}" height="${i===1?941:1024}" loading="lazy" alt="${escapeHTML(title)} 디자인 작업 무드보드" data-parallax></div><h3>${escapeHTML(title)}</h3><div class="service-detail"><div class="tags">${tags.map(t=>`<span class="tag"><img src="assets/check.svg" width="24" height="24" alt="">${escapeHTML(t)}</span>`).join('')}</div><p>${escapeHTML(desc)}</p></div></article>`).join('')}</div></section>
    <section class="section about-section" id="about" aria-labelledby="about-title"><h2 class="reveal" id="about-title">About me</h2><p class="about-intro">일상의 경험을 더 나은 디자인으로 연결하는<br> BX 디자이너입니다.</p><div class="about-split"><div class="portrait reveal"><img src="assets/about.png" width="1536" height="1024" loading="lazy" alt="노트북으로 디자인 작업 중인 지혜" data-parallax></div><div class="about-statement"><p class="about-body">브랜드와 사용자를 이해하고,<br> 문제를 발견해 기획과<br> 디자인으로 풀어내는 과정을 좋아합니다.<br> <br> 브랜드의 방향을 고민하는 일부터<br> 웹·모바일 화면까지, 사람들이 더 쉽고,<br> 더 즐겁게 경험할 수 있는<br> 디자인을 만들고자 합니다.</p><a class="cta roll upper reveal" href="#contact">Get in Touch ↗</a></div></div></section>${contact()}${footer()}`;
}

function work() {
  return `<section class="section work-section" id="work"><div class="section-heading reveal"><h1 class="work-title">Selected Work</h1><p class="work-description">브랜드부터 디지털까지, 다양한 디자인 프로젝트를 소개합니다.</p></div><p class="work-year reveal">© 2026</p><div class="filters reveal" role="group" aria-label="프로젝트 카테고리">${['All','Branding','UI/UX Design','Website Design','Strategy & Research'].map((s,i)=>`<button type="button" class="roll" data-filter="${escapeHTML(s)}" aria-pressed="${i===0}">${escapeHTML(s)}</button>`).join('')}</div><div class="project-grid">${projects.map((p,i)=>projectCard(p,i,true)).join('')}</div><p class="empty-state" hidden>선택한 분야의 프로젝트가 아직 등록되지 않았습니다.</p></section>${contact()}${footer()}`;
}

function detailMeta(items) {return `<dl class="detail-meta reveal">${items.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
function caseNavigation(other) {return `<nav class="case-navigation section reveal" aria-label="다른 프로젝트 탐색"><a class="roll" href="#/work">← All Projects</a><a class="roll" href="#/work/${other.toLowerCase()}">Next / ${other} ↗</a></nav>`;}

function mova() {
  return renderMovaGallery()+caseNavigation('MOVERA')+contact()+footer();
}

function researchCard(label,title,body) {return `<div class="research-card"><p class="eyebrow">${label}</p><h3>${title}</h3><p>${body}</p></div>`;}
function scenarios(extra='') {return `<div class="scenario-list ${extra}">${[['01 / WORKDAY','출근길, 단정하게'],['02 / AFTER HOURS','퇴근 후, 가볍게'],['03 / WEEKEND','주말에도, 편안하게']].map(([a,b])=>`<div class="scenario"><p class="eyebrow">${a}</p><p>${b}</p></div>`).join('')}</div>`;}

function movera() {
  const bars=[['착용 상황',19],['핏·사이즈',15],['착용감',14],['품질',12],['소재',12],['코디·활용도',11]];
  return `<article class="case-study movera">
    <section class="section"><h1 class="work-title reveal">MOVERA</h1><p class="work-description reveal">한 벌의 옷을 여러 코디와 일상 장면으로 연결하는<br> 데일리웨어 브랜드 기획 프로젝트</p>${detailMeta([['PROJECT','SPA · BX 기획'],['MY ROLE','리서치 · 언어 기획'],['RESEARCH','경쟁사 5곳 · VOC 100건'],['OUTPUT','브랜드 언어 · 랜딩 시안']])}
      <div class="movera-hero reveal"><img src="assets/movera.png" width="768" height="512" alt="다양한 옷과 착용 장면을 담은 MOVERA 콘셉트" data-parallax><div class="movera-hero-content"><div class="movera-hero-copy"><p class="eyebrow">BRAND EXPERIENCE / CONCEPT PROJECT</p><h2>MOVERA</h2><h3>자주 입는 옷에는 이유가 있다.</h3><p>다양한 코디와 일상 장면으로 이어지는<br>한 벌의 가능성을 제안합니다.</p></div><div class="movera-moments"><p class="eyebrow">ONE PIECE, MANY MOMENTS · 활용 장면 예시</p>${scenarios()}</div></div></div>
    </section>
    <section class="section"><h2 class="reveal">01 / 문제 정의</h2><p class="detail-body read-text">옷을 고를 때, 활용 장면을 고객이 직접 상상해야 했다.</p><p class="reveal muted">경쟁사 첫 화면은 행사·시즌·스타일 중심. 수집한 VOC에서는 착용 상황과 활용도에 관한 언급이 확인됐다.</p><div class="research-panel reveal"><h3 class="panel-title">관찰에서 문제 가설까지</h3><div class="research-grid three">${researchCard('01 / 경쟁사 첫 화면','5개 브랜드 비교','할인·시즌·스타일·프로젝트가 첫 화면의 주요 제안이었다.<br>구체적인 착용 상황 제안은 확인한 첫 화면에서 보이지 않았다.')}${researchCard('02 / 고객 목소리','VOC 100건','수집한 리뷰에서 착용 상황 관련 언급 19건을 분류했다.<br>활용 장면이 고객 경험에서 언급된다는 근거를 확인했다.')}${researchCard('03 / 문제 가설','활용도 판단의 부담','여러 상황에서 입을 수 있을지 고객이 직접 판단해야 한다는 가설을 세웠다. 이후 단계에서 추가 검증이 필요하다.')}</div><p class="insight-strip">핵심 질문 / 한 벌의 다양한 착용 상황을 어떻게 더 쉽게 보여줄 수 있을까?</p></div></section>
    <section class="section"><h2 class="reveal">02 / 리서치</h2><p class="detail-body read-text">고객은 구체적인 착용 장면을 말하지만, 비교한 첫 화면은 시즌·행사·스타일을 앞세웠다.</p><p class="muted reveal">SPA 브랜드 5곳의 첫 화면(2026.10.01)과 상품 리뷰 100건을 비교했습니다.</p>
      <div class="research-panel reveal"><h3 class="panel-title">A. 경쟁사 랜딩 첫 화면 / 5개 브랜드</h3><div class="research-grid three competitor">${researchCard('3곳','가격·행사 중심','무신사 스탠다드 · 유니클로 · 탑텐')}${researchCard('1곳','스타일 제안 중심','스파오')}${researchCard('1곳','프로젝트 콘텐츠 중심','자라')}</div><p class="muted">다섯 화면에서 출근·이동·주말처럼 구체적인 착용 상황을 전면에 제시한 사례는 확인되지 않았습니다.</p></div>
      <div class="research-panel reveal"><h3 class="panel-title">B. VOC 100건 / 무엇을 경험으로 말했나</h3><div class="research-grid two"><div class="research-card"><h3>주요 언급 카테고리</h3><div class="bar-chart" role="img" aria-label="VOC 주요 카테고리: 착용 상황 19건, 핏·사이즈 15건, 착용감 14건, 품질 12건, 소재 12건, 코디·활용도 11건">${bars.map(([label,num])=>`<div class="bar-row"><span>${label}</span><span class="bar-track"><span class="bar" style="--bar:${num/19*100}%"></span></span><strong>${num}건</strong></div>`).join('')}</div><p class="small muted">상위 6개 분류만 표시 · 리뷰 1건당 주요 카테고리 1개</p></div><div class="research-card voc-highlight"><p class="eyebrow">가장 많이 언급된 경험</p><strong class="stat">19건</strong><h3>긍정 8 · 중립 10 · 부정 1</h3><p>착용 상황은 가장 자주 언급됐지만 부정은 1건입니다.<br>불만이 크다고 단정하지 않고, 상황별 상품 제안의 가능성으로 읽었습니다.</p></div></div></div>
      <div class="key-finding reveal"><p class="eyebrow">KEY FINDING</p><p>고객의 언어에는 착용 장면이 반복되지만, 비교한 첫 화면에서는 그 장면을 앞세운 제안을 확인하지 못했습니다.</p></div><p class="small muted reveal">출처: Day38 경쟁사 랜딩 비교(2026.10.01), Day39 SPA VOC 100건.<br>해석 범위: 수집한 첫 화면과 리뷰 표본에 한정됩니다.</p>
    </section>
    <section class="section"><h2 class="reveal">03 / 전략</h2><p class="detail-body read-text">한 벌을 여러 일상 장면으로 보여주는 ‘상황 중심 제안’을 선택했다.</p><p class="muted reveal">착용 상황 언급 19건과 경쟁사 첫 화면에서 확인한 제안 방식을 연결해, 추상적 활용도 대신 실제 입는 장면을 보여주기로 했습니다.</p><div class="research-grid three strategy reveal">${researchCard('01 / 관찰','착용 상황 19건으로<br>가장 많이 언급됨.','19건 · 부정 1건')}${researchCard('02 / 빈틈','비교한 첫 화면에서<br>구체적 착용 장면 미확인.','첫 화면 표본에 한정')}${researchCard('03 / 선택','한 벌을 여러 장면과<br>코디로 연결.','상황 중심 제안')}</div><div class="research-panel reveal"><h3 class="panel-title">선택한 브랜드 표현</h3><div class="research-grid two">${researchCard('BRAND CONCEPT','여러 코디를 위해 옷을 만듭니다.','한 벌의 활용 가능성을 일상의 실제 장면으로 설명합니다.')}${researchCard('BRAND LANGUAGE','모베라 MOVERA','자주 입는 옷에는 이유가 있다.<br>실용적인 · 편안한 · 담백한 · 트렌디한')}</div></div><p class="small muted reveal">이 방향은 리서치와 브랜드 기획을 바탕으로 정한 시안이며, 실제 고객 반응으로 검증된 결과는 아닙니다.</p></section>
    <section class="section"><h2 class="reveal">04 / 결과</h2><p class="detail-body read-text">컨셉·이름·카피를 하나의 랜딩 경험으로 묶었다.</p><p class="muted reveal">브랜드 언어 자산을 정리하고, 일상 장면을 먼저 보여주는 랜딩 카피 시안으로 구체화했습니다.</p><div class="result-stats reveal">${[['3 → 1','브랜드 콘셉트'],['10 → 1','네이밍'],['6 → 1','슬로건']].map(([a,b])=>`<div><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><div class="research-panel landing-concept reveal"><div class="concept-header"><strong>MOVERA</strong><span>LANDING COPY / CONCEPT DRAFT</span></div><div class="research-grid two"><div class="research-card"><h3>오늘도 다른 옷처럼</h3><p>출근부터 주말까지, 여러 코디로 이어지는<br>MOVERA의 옷을 만나보세요.</p><span class="concept-cta">스타일 제안 보기</span></div>${scenarios()}</div></div><p class="small muted reveal">결과물은 브랜드 언어와 랜딩 카피 시안입니다. 실제 출시, 전환율, 고객 반응 수치는 아직 없습니다.</p></section>
    <section class="section"><h2 class="reveal">05 / 배운 점</h2><p class="detail-body read-text">제안의 근거와 검증의 범위를 함께 보여줘야 한다.</p><p class="muted reveal">이 프로젝트는 리서치로 방향을 정하고 언어·랜딩 시안까지 만들었지만, 고객 반응을 검증하는 단계는 남아 있습니다.</p><div class="research-grid two lessons reveal">${researchCard('01 / 언급 빈도 ≠ 불만 크기','착용 상황 19건 중 부정은 1건.','언급 빈도를 불만의 크기로 읽지 않았습니다.')}${researchCard('02 / 첫 화면 관찰 ≠ 시장 전체','수집 당시 첫 화면 5곳만 비교했습니다.','이를 시장 전체의 빈틈으로 일반화하지 않았습니다.')}</div><div class="key-finding next-plan reveal"><p class="eyebrow">NEXT / 사용자 검증</p><h3>상황 중심 카피가 고객의 상품 탐색을 실제로 돕는지 확인하겠습니다.</h3><div class="validation-questions"><span>01 착용 장면을 바로 이해하는가?</span><span>02 원하는 코디를 쉽게 찾는가?</span><span>03 CTA가 다음 행동을 알려주는가?</span></div></div><p class="small muted reveal">사용자 테스트와 실제 전환 데이터는 아직 확보하지 않았습니다. 위 질문은 다음 검증 계획입니다.</p></section>
    </article>${caseNavigation('MOVA')}${contact()}${footer()}`;
}

let currentPage='',routeBusy=false,observer=null,reading=[];
function pageFromHash(hash){const path=hash.split('?')[0];return path==='#/work/movera'?'movera':path==='#/work/mova'||path==='#/case'?'mova':path==='#/work'?'work':'home';}
function makeRolling(root=document){root.querySelectorAll('.roll:not([data-roll-ready])').forEach(el=>{const value=el.textContent.trim();el.dataset.rollReady='true';if(!el.hasAttribute('aria-label'))el.setAttribute('aria-label',value);const outer=document.createElement('span');outer.className='roll-text';outer.setAttribute('aria-hidden','true');let groups=[value];if(el.matches('[data-filter]')){outer.classList.add('multiline');if(value==='UI/UX Design')groups=['UI/UX','Design'];if(value==='Website Design')groups=['Website','Design'];if(value==='Strategy & Research')groups=['Strategy &','Research'];}let idx=0;for(const group of groups){const line=document.createElement('span');line.className='roll-line';graphemes(group).forEach(c=>{const letter=document.createElement('span');letter.className='roll-letter';letter.style.setProperty('--i',idx++);for(const cls of ['roll-front','roll-back']){const span=document.createElement('span');span.className=cls;span.textContent=c===' '?'\u00a0':c;letter.append(span);}line.append(letter);});outer.append(line);}el.replaceChildren(outer);});}
function splitReadText(el){el.setAttribute('aria-label',el.textContent);const fragment=document.createDocumentFragment();for(const node of [...el.childNodes]){if(node.nodeType===Node.ELEMENT_NODE){fragment.append(node.cloneNode(true));continue;}for(const word of (node.textContent||'').split(/(\s+)/)){if(!word)continue;if(/^\s+$/.test(word)){fragment.append(document.createTextNode(word));continue;}const group=document.createElement('span');group.className='read-word';group.setAttribute('aria-hidden','true');for(const char of graphemes(word)){const c=document.createElement('span');c.className='read-char';c.textContent=char;group.append(c);}fragment.append(group);}}el.replaceChildren(fragment);return {el,chars:[...el.querySelectorAll('.read-char')]};}
function initView(){main.querySelectorAll('.work-title').forEach(el=>{const label=el.textContent;el.setAttribute('aria-label',label);let i=0;el.innerHTML=label.split(' ').map(word=>'<span class="title-word" aria-hidden="true">'+graphemes(word).map(c=>'<span class="title-char" style="--i:'+(i++)+'">'+escapeHTML(c)+'</span>').join('')+'</span>').join(' ');});makeRolling();initFooterMotion();initGallery();observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}},{threshold:.08,rootMargin:'0px 0px -5% 0px'});main.querySelectorAll('.reveal').forEach(el=>observer.observe(el));reading=[...main.querySelectorAll('.read-text')].filter(el=>!el.closest('#about')).map(splitReadText);initForm();updateScroll();document.title=({work:'Selected Work',mova:'MOVA',movera:'MOVERA'}[currentPage]||'BX & Brand Designer')+' — Jihye Min';document.body.dataset.page=currentPage;document.querySelectorAll('.header nav a').forEach(a=>{const active=currentPage==='home'?a.getAttribute('href')==='#home':a.getAttribute('href')==='#/work';if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function render(page){currentPage=page;main.innerHTML=page==='work'?work():page==='mova'?mova():page==='movera'?movera():landing();initView();}
async function go(hash,replace=false){if(routeBusy)return;const targetPage=pageFromHash(hash);closeMenu();cursor.classList.remove('visible');if(targetPage!==currentPage){routeBusy=true;const cover=document.querySelector('.transition-cover');if(!reduceMotion.matches){cover.className='transition-cover enter';await new Promise(r=>setTimeout(r,450));}render(targetPage);window.scrollTo({top:0,behavior:'instant'});if(!reduceMotion.matches){await new Promise(r=>requestAnimationFrame(r));cover.className='transition-cover exit';setTimeout(()=>{cover.className='transition-cover';},650);}routeBusy=false;main.focus({preventScroll:true});}if(replace)history.replaceState(null,'',hash);else if(location.hash!==hash)history.pushState(null,'',hash);if(targetPage==='home'&&['#home','#about','#contact','#work'].includes(hash)){const target=main.querySelector(hash);target?.scrollIntoView({behavior:reduceMotion.matches?'instant':'smooth',block:'start'});}else if(hash==='#contact'){main.querySelector('#contact')?.scrollIntoView({behavior:reduceMotion.matches?'instant':'smooth'});}}
const toggle=document.querySelector('.menu-toggle'),mobileMenu=document.querySelector('.mobile-menu');
function closeMenu(){document.body.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','메뉴 열기');mobileMenu.inert=true;}
toggle.addEventListener('click',()=>{const open=!document.body.classList.contains('menu-open');document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');mobileMenu.inert=!open;if(open)setTimeout(()=>mobileMenu.querySelector('a').focus(),150);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();toggle.focus();}if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const links=[toggle,...mobileMenu.querySelectorAll('a')];if(e.shiftKey&&document.activeElement===links[0]){e.preventDefault();links.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===links.at(-1)){e.preventDefault();links[0].focus();}}});
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(link&&link.getAttribute('href')!=='#main'&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();let hash=link.getAttribute('href');if(hash==='#contact'&&currentPage!=='home'){closeMenu();main.querySelector('#contact')?.scrollIntoView({behavior:reduceMotion.matches?'instant':'smooth'});return;}go(hash);}const filter=e.target.closest('[data-filter]');if(filter){main.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===filter)));const category=filter.dataset.filter;let shown=0;main.querySelectorAll('[data-project]').forEach(c=>{const p=projects.find(p=>p.slug===c.dataset.project);c.hidden=category!=='All'&&!p.categories.includes(category);if(!c.hidden){shown++;c.classList.remove('filter-enter');requestAnimationFrame(()=>c.classList.add('filter-enter'));}c.classList.add('in-view');});main.querySelector('.empty-state').hidden=shown>0;}const info=e.target.closest('[data-info]');if(info)showInfo(info.dataset.info);});
window.addEventListener('popstate',()=>go(location.hash||'#home',true));
window.addEventListener('hashchange',()=>go(location.hash||'#home',true));
const dialog=document.querySelector('dialog');dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function showInfo(type){const messages={privacy:['Privacy Policy','문의 폼에서 작성한 내용은 이 사이트의 서버로 전송되지 않습니다. Send Message를 선택하면 사용자의 메일 앱으로 내용이 전달되며, 실제 전송은 메일 앱에서 완료됩니다. 별도의 분석 쿠키는 사용하지 않습니다.'],terms:['Terms & Conditions','이 포트폴리오의 디자인과 콘텐츠를 무단으로 재배포하지 말아 주세요. 프로젝트 비주얼 및 일부 문구는 피그마 와이어프레임의 자리표시자입니다.'],instagram:['Instagram','Instagram 계정 링크를 준비하고 있습니다. 문의는 '+CONTACT_EMAIL+'으로 보내 주세요.'],profile:['Profile','프로필 링크를 준비하고 있습니다. 문의는 '+CONTACT_EMAIL+'으로 보내 주세요.'],youtube:['YouTube','YouTube 채널 링크를 준비하고 있습니다. 문의는 '+CONTACT_EMAIL+'으로 보내 주세요.']};const [title,body]=messages[type]||messages.profile;dialog.querySelector('h2').textContent=title;dialog.querySelector('p').textContent=body;dialog.showModal();}
function initForm(){const form=main.querySelector('form');if(!form)return;const fields=[...form.querySelectorAll('input,select,textarea')];function validate(el){let error='';if(!el.value.trim())error=el.name==='service'?'서비스를 선택해 주세요.':'내용을 입력해 주세요.';else if(el.type==='email'&&!el.validity.valid)error='올바른 이메일 주소를 입력해 주세요.';el.setAttribute('aria-invalid',String(!!error));form.querySelector('#'+el.id+'-error').textContent=error;return !error;}fields.forEach(el=>{el.addEventListener('blur',()=>validate(el));el.addEventListener('input',()=>{if(el.getAttribute('aria-invalid')==='true')validate(el);form.querySelector('.form-status').textContent='';});});form.addEventListener('submit',e=>{e.preventDefault();let valid=true;fields.forEach(el=>{if(!validate(el))valid=false;});if(!valid){form.querySelector('[aria-invalid=true]')?.focus();return;}const data=new FormData(form);const subject=`[디자인 문의] ${data.get('service')} — ${data.get('name')}`;const body=`이름: ${data.get('name')}\n이메일: ${data.get('email')}\n서비스: ${data.get('service')}\n\n${data.get('message')}`;const href=`mailto:${CONTACT_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;const mail=document.createElement('a');mail.href=href;mail.hidden=true;document.body.append(mail);mail.click();mail.remove();form.querySelector('.form-status').textContent='메일 작성 창을 열었습니다. 메일 앱에서 전송을 완료해 주세요. 창이 열리지 않았다면 '+CONTACT_EMAIL+'으로 직접 보내 주세요.';});}
let pendingScroll=false;function updateScroll(){pendingScroll=false;document.querySelector('.header').classList.toggle('is-scrolled',scrollY>20);if(!reduceMotion.matches){main.querySelectorAll('[data-parallax]').forEach(img=>{const rect=img.parentElement.getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight){const n=(innerHeight/2-rect.top-rect.height/2)/innerHeight;img.style.setProperty('--parallax',Math.max(-22,Math.min(22,n*32))+'px');}});}for(const {el,chars}of reading){const rect=el.getBoundingClientRect();const progress=reduceMotion.matches?1:Math.max(0,Math.min(1,(innerHeight*.92-rect.top)/(innerHeight*.42+rect.height)));chars.forEach((c,i)=>c.classList.toggle('is-lit',i/chars.length<progress));}}
addEventListener('scroll',()=>{if(!pendingScroll){pendingScroll=true;requestAnimationFrame(updateScroll);}},{passive:true});addEventListener('resize',updateScroll);
const cursor=document.querySelector('.project-cursor');let pointer={x:0,y:0},cursorPoint={x:0,y:0},cursorRAF=0;
function followCursor(){cursorPoint.x+=(pointer.x-cursorPoint.x)*.2;cursorPoint.y+=(pointer.y-cursorPoint.y)*.2;cursor.style.translate=`${cursorPoint.x}px ${cursorPoint.y}px`;if(cursor.classList.contains('visible'))cursorRAF=requestAnimationFrame(followCursor);else cursorRAF=0;}
document.addEventListener('pointermove',e=>{if(!finePointer.matches||reduceMotion.matches)return;pointer={x:e.clientX,y:e.clientY};const target=e.target.closest('[data-cursor]');if(target){cursor.querySelector('span').textContent=target.dataset.cursor;if(!cursor.classList.contains('visible')){cursorPoint={...pointer};cursor.classList.add('visible');}if(!cursorRAF)followCursor();}else cursor.classList.remove('visible');},{passive:true});document.addEventListener('pointerleave',()=>cursor.classList.remove('visible'));
render(pageFromHash(location.hash));document.fonts.ready.then(()=>{updateScroll();if(['#about','#contact'].includes(location.hash))main.querySelector(location.hash)?.scrollIntoView({behavior:'instant'});});

function initFooterMotion(){
  const name=main.querySelector('.footer-name');
  if(!name)return;
  const letters=[...name.querySelectorAll('.footer-letter')];
  let frame=0,point=null;
  const reset=()=>{point=null;cancelAnimationFrame(frame);frame=0;letters.forEach(c=>{c.style.removeProperty('transform');c.style.removeProperty('color');});};
  const paint=()=>{frame=0;if(!point||reduceMotion.matches)return;
    const rect=name.getBoundingClientRect();
    const radius=rect.width*.22;
    const dy=(point.y-(rect.top+rect.height/2))*.12;
    letters.forEach(c=>{
      const r=c.getBoundingClientRect();
      const strength=Math.max(0,1-Math.abs(point.x-(r.left+r.width/2))/radius);
      c.style.transform=`translateY(${dy*strength}px)`;
      c.style.color=`color-mix(in srgb, #fff ${strength*100}%, var(--muted))`;
    });
  };
  name.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||reduceMotion.matches)return;point={x:e.clientX,y:e.clientY};if(!frame)frame=requestAnimationFrame(paint);});
  name.addEventListener('pointerleave',reset);
  name.addEventListener('pointercancel',reset);
  reduceMotion.addEventListener('change',reset,{once:true});
}
